100	   */
101	  isInScope(filePath: string): boolean {
102	    const resolved = path.resolve(filePath);
103	    return resolved === this.specDir || resolved.startsWith(this.specDir + path.sep);
104	  }
105	
106	  /**
107	   * Write a file to the buffer.
108	   * AC: @batch-write-buffer ac-1
109	   */
110	  write(filePath: string, content: string): void {
111	    this.entries.set(path.resolve(filePath), content);
112	  }
113	
114	  /**
115	   * Mark a file as deleted in the buffer.
116	   */
117	  delete(filePath: string): void {
118	    this.entries.set(path.resolve(filePath), null);
119	  }
120	
121	  /**
122	   * Check if a file path has a buffered entry (write or delete).
123	   */
124	  has(filePath: string): boolean {
125	    return this.entries.has(path.resolve(filePath));
126	  }
127	
128	  /**
