161	  private _buildDirectoryOverlay(directory: string): BufferedDirectoryOverlay {
162	    const resolvedDir = path.resolve(directory);
163	    const directWrites = new Map<string, "file" | "deleted">();
164	    const inferredDirectories = new Set<string>();
165	
166	    for (const [bufferedPath, content] of this.entries) {
167	      const relative = path.relative(resolvedDir, bufferedPath);
168	      if (!relative || relative.startsWith("..") || path.isAbsolute(relative)) {
