188	   * Used to keep batch read-after-write semantics for readdir callers.
189	   */
190	  async listDir(
191	    directory: string,
192	    options?: { withFileTypes?: boolean },
193	  ): Promise<string[] | Dirent[]> {
194	    const resolvedDir = path.resolve(directory);
