482	async function getAllFiles(dir: string): Promise<string[]> {
483	  const results: string[] = [];
484	  try {
485	    const entries = await fs.readdir(dir, { withFileTypes: true });
486	    for (const entry of entries) {
487	      const fullPath = path.join(dir, entry.name);
488	      if (entry.isDirectory()) {
489	        const sub = await getAllFiles(fullPath);
490	        results.push(...sub);
491	      } else {
492	        results.push(fullPath);
493	      }
494	    }
495	  } catch {
496	    // ignore
497	  }
498	  return results;
499	}

