553	  // task state to a temp directory; scanning ctx.rootDir can leak tasks from parent dirs.
554	  if (ctx.shadow?.enabled || Boolean(process.env.KSPEC_SPEC_DIR)) {
555	    const taskFiles = await findTaskFiles(ctx.specDir);
556	
557	    // Also check for standalone files in specDir
558	    const standaloneLocations = [
