605	    path.join(ctx.rootDir, "spec", "project.tasks.yaml"),
606	    path.join(ctx.rootDir, "backlog.tasks.yaml"),
607	    path.join(ctx.rootDir, "active.tasks.yaml"),
608	  ];
609	
