1075	/**
1076	 * Expand a glob-like include pattern to file paths.
1077	 * Supports simple patterns like "modules/*.yaml" or "**\/*.yaml"
1078	 */
1079	export async function expandIncludePattern(
1080	  pattern: string,
1081	  baseDir: string,
1082	): Promise<string[]> {
1083	  const fullPattern = path.isAbsolute(pattern)
1084	    ? pattern
1085	    : path.join(baseDir, pattern);
1086	
1087	  // If no glob characters, just return the path if it exists
1088	  if (!pattern.includes("*")) {
1089	    try {
1090	      await accessBufferAware(fullPattern);
1091	      return [fullPattern];
1092	    } catch {
1093	      return [];
1094	    }
1095	  }
1096	
1097	  // Split pattern into directory part and file pattern
1098	  const parts = pattern.split("/");
1099	  let currentDir = baseDir;
1100	  const result: string[] = [];
1101	
1102	  // Find the first part with a glob
1103	  const globIndex = parts.findIndex((p) => p.includes("*"));
1104	
1105	  // Navigate to the directory before the glob
1106	  if (globIndex > 0) {
1107	    currentDir = path.join(baseDir, ...parts.slice(0, globIndex));
1108	  }
1109	
1110	  // Get the remaining pattern
1111	  const remainingPattern = parts.slice(globIndex).join("/");
1112	
1113	  await expandGlobRecursive(currentDir, remainingPattern, result);
