1120	async function expandGlobRecursive(
1121	  dir: string,
1122	  pattern: string,
1123	  result: string[],
1124	): Promise<void> {
1125	  const parts = pattern.split("/");
1126	  const currentPattern = parts[0];
1127	  const remainingPattern = parts.slice(1).join("/");
1128	
1129	  try {
1130	    const entries = await readdirBufferAware(dir, { withFileTypes: true }) as Dirent[];
1131	
1132	    for (const entry of entries) {
1133	      const matches = matchGlobPart(entry.name, currentPattern);
1134	
1135	      if (matches) {
1136	        const fullPath = path.join(dir, entry.name);
1137	
1138	        if (remainingPattern) {
1139	          // More pattern parts to process
1140	          if (entry.isDirectory()) {
1141	            await expandGlobRecursive(fullPath, remainingPattern, result);
1142	          }
1143	        } else {
1144	          // This is the final pattern part
1145	          if (currentPattern === "**") {
1146	            // ** matches any depth - need special handling
1147	            if (entry.isDirectory()) {
1148	              await expandGlobRecursive(fullPath, "**", result);
1149	            }
1150	            // Also match files at this level
1151	            result.push(fullPath);
1152	          } else if (entry.isFile()) {
1153	            result.push(fullPath);
1154	          }
1155	        }
1156	      }
1157	
1158	      // Handle ** - also recurse into directories without consuming the pattern
1159	      if (currentPattern === "**" && entry.isDirectory()) {
1160	        const fullPath = path.join(dir, entry.name);
1161	        await expandGlobRecursive(fullPath, pattern, result);
