1169	/**
1170	 * Match a single path component against a glob pattern part
1171	 */
1172	function matchGlobPart(name: string, pattern: string): boolean {
1173	  if (pattern === "*") return true;
1174	  if (pattern === "**") return true;
1175	
1176	  // Convert glob pattern to regex
1177	  const regexPattern = pattern
1178	    .replace(/[.+^${}()|[\]\\]/g, "\\$&") // Escape special regex chars
1179	    .replace(/\*/g, ".*") // * matches anything
1180	    .replace(/\?/g, "."); // ? matches single char
1181	
1182	  const regex = new RegExp(`^${regexPattern}$`);
1183	  return regex.test(name);
