1204	export function extractItemsFromRaw(
1205	  raw: unknown,
1206	  sourceFile: string,
1207	  items: LoadedSpecItem[] = [],
1208	  currentPath: string = "",
1209	): LoadedSpecItem[] {
1210	  if (!raw || typeof raw !== "object") {
1211	    return items;
1212	  }
1213	
1214	  // Check if this object is itself a spec item (has _ulid)
1215	  if (
1216	    "_ulid" in raw &&
1217	    typeof (raw as Record<string, unknown>)._ulid === "string"
1218	  ) {
1219	    // Strip nested item arrays before validation since they're processed separately
1220	    // and the SpecItemSchema expects refs (strings), not nested objects
1221	    const rawObj = raw as Record<string, unknown>;
1222	    const cleanedForValidation: Record<string, unknown> = { ...rawObj };
1223	    for (const field of NESTED_ITEM_FIELDS) {
1224	      if (field in cleanedForValidation && Array.isArray(cleanedForValidation[field])) {
1225	        const arr = cleanedForValidation[field] as unknown[];
1226	        // Check if array contains nested items (objects with _ulid) vs refs (strings)
1227	        const hasNestedItems = arr.some(
1228	          (item) =>
1229	            item && typeof item === "object" && "_ulid" in (item as Record<string, unknown>)
1230	        );
1231	        if (hasNestedItems) {
1232	          // Strip nested items - they'll be extracted recursively
1233	          delete cleanedForValidation[field];
1234	        }
1235	      }
1236	    }
1237	
1238	    const result = SpecItemSchema.safeParse(cleanedForValidation);
1239	    if (result.success) {
1240	      items.push({
1241	        ...result.data,
1242	        _sourceFile: sourceFile,
1243	        _path: currentPath || undefined,
1244	      });
1245	    }
1246	
1247	    // Even if the item itself was added, also extract nested items
1248	    for (const field of NESTED_ITEM_FIELDS) {
1249	      if (field in rawObj && Array.isArray(rawObj[field])) {
1250	        const arr = rawObj[field] as unknown[];
1251	        for (let i = 0; i < arr.length; i++) {
1252	          const nestedPath = currentPath
1253	            ? `${currentPath}.${field}[${i}]`
1254	            : `${field}[${i}]`;
1255	          extractItemsFromRaw(arr[i], sourceFile, items, nestedPath);
1256	        }
1257	      }
1258	    }
1259	  } else if (Array.isArray(raw)) {
1260	    // Array of items at root level
1261	    for (let i = 0; i < raw.length; i++) {
1262	      const itemPath = currentPath ? `${currentPath}[${i}]` : `[${i}]`;
1263	      extractItemsFromRaw(raw[i], sourceFile, items, itemPath);
1264	    }
1265	  } else {
1266	    // Object that might contain item arrays (like manifest with modules/features/etc)
1267	    const rawObj = raw as Record<string, unknown>;
1268	    for (const field of NESTED_ITEM_FIELDS) {
1269	      if (field in rawObj && Array.isArray(rawObj[field])) {
