1271	        for (let i = 0; i < arr.length; i++) {
1272	          const nestedPath = currentPath
1273	            ? `${currentPath}.${field}[${i}]`
1274	            : `${field}[${i}]`;
1275	          extractItemsFromRaw(arr[i], sourceFile, items, nestedPath);
